/* Searchable bilingual library of 120 practical subscription and app troubleshooting answers. */
(function(root,factory){
 const api=factory(root);
 if(typeof module==='object'&&module.exports)module.exports=api;
 else root.MasterCommonProblems=api;
 if(typeof document!=='undefined')api.mount(document);
})(typeof window==='undefined'?globalThis:window,function(global){
'use strict';
const problems=[];
function add(category,rows){for(const r of rows)problems.push({id:problems.length+1,category,question:r[0],answer:r[1],questionEn:r[2],answerEn:r[3]});}
add('account',[
["مش قادر أسجل الدخول رغم أن البيانات صحيحة","تأكد من البريد وطريقة الدخول المستخدمة أول مرة، مثل كلمة المرور أو Google أو Apple. جرّب كتابة البريد يدويًا، وافحص لغة لوحة المفاتيح. لو الحساب جاهز، لا تعِد تعيين كلمة المرور قبل مراجعة تعليمات التسليم.","I cannot sign in although the details look correct","Use the same email and sign-in method used originally, such as password, Google or Apple. Type the email manually and check your keyboard layout. For a ready account, do not reset the password before checking delivery instructions."],
["كلمة المرور تظهر خطأ كل مرة","تأكد من عدم وجود مسافة قبل أو بعد كلمة المرور ومن حالة Caps Lock. انسخ البيانات من رسالة التسليم الأصلية. لا تجرّب تخمينات كثيرة؛ إذا كان الحساب جاهزًا أرسل الخطأ للدعم.","The password is rejected every time","Check for spaces before or after the password and check Caps Lock. Copy the details from the original delivery message. Avoid repeated guesses; if it is a ready account, send the error to support."],
["صفحة تسجيل الدخول ترجعني لنفس المكان","اسمح بملفات تعريف الارتباط، وجرّب نافذة خاصة أو متصفحًا محدثًا. أوقف إضافات الحجب مؤقتًا للاختبار، ثم افتح الموقع الرسمي من جديد.","The sign-in page keeps returning to the same screen","Allow cookies and try a private window or updated browser. Temporarily test without blocking extensions, then reopen the provider’s official website."],
["الحساب يسجل خروجي تلقائيًا","قد تنتهي الجلسة لأسباب أمنية أو بسبب تغيير كلمة المرور أو استخدام أجهزة متعددة. حدّث التطبيق، وتأكد من اتصال ثابت، وراجع حدود الأجهزة المسموحة في الخطة.","The account keeps signing me out","Sessions may expire for security reasons, after a password change or when multiple devices are used. Update the app, use a stable connection and check the plan’s device limits."],
["دخلت على حساب مختلف عن حساب الاشتراك","سجّل الخروج وتأكد من البريد الظاهر أعلى صفحة الحساب قبل الدخول مجددًا. إذا استخدمت تسجيل Google أو Apple، اختر الحساب الصحيح نفسه المرتبط بالباقة.","I opened a different account from the subscribed one","Sign out and check the email shown in the account page before signing in again. If you use Google or Apple sign-in, select the same account linked to the plan."],
["رمز التحقق بخطوتين لا يعمل","استخدم أحدث رمز وصلك فقط، وتأكد من ضبط التاريخ والوقت تلقائيًا على الهاتف. لا تطلب رموزًا كثيرة متتالية؛ انتظر قليلًا ثم اطلب رمزًا جديدًا.","Two-step verification code does not work","Use only the newest code and set your phone’s date and time automatically. Avoid requesting many codes in a row; wait briefly and request a fresh one."],
["الحساب اتقفل بعد محاولات تسجيل كثيرة","أوقف المحاولات مؤقتًا واتبع رسالة الاسترداد الرسمية من المزود. لا تستخدم روابط استرداد من رسائل مجهولة، واحتفظ بصورة رسالة القفل ورقم الطلب إذا كان الحساب من المتجر.","The account was locked after repeated sign-in attempts","Stop trying for a while and follow the provider’s official recovery flow. Avoid recovery links from unknown messages. Keep a screenshot of the lock notice and your order reference if the account came from the store."],
["وصلني تنبيه بدخول غير معروف","لو الحساب شخصي، افتح صفحة الأمان الرسمية وراجع الجلسات وغيّر كلمة المرور عند الاشتباه. لو الحساب جاهز، لا تغيّر بياناته بنفسك؛ تواصل مع الدعم فورًا.","I received an unfamiliar sign-in alert","For a personal account, open the official security page, review sessions and change the password if compromised. For a ready account, do not change its details yourself; contact support immediately."],
["الموقع يقول إن الحساب غير موجود","تأكد من كتابة البريد كاملًا ومن عدم وجود خطأ في النطاق. جرّب طريقة الدخول الأصلية؛ بعض الخدمات تنشئ الحساب عبر Google أو Apple ولا تستخدم كلمة مرور منفصلة.","The website says the account does not exist","Check the full email address and domain for typos. Try the original sign-in method; some services create accounts through Google or Apple without a separate password."],
["الخدمة لا تسمح بأكثر من جهاز","راجع شروط الخطة وعدد الأجهزة أو الجلسات المتزامنة. سجّل الخروج من جهاز قديم إذا كان مسموحًا، ولا تفترض أن الاشتراك يتيح مشاركة الدخول بلا حدود.","The service will not allow another device","Check the plan’s device or simultaneous-session limits. Sign out of an old device if permitted, and do not assume the subscription allows unlimited account sharing."]
]);
add('email',[
["رمز التفعيل لم يصل إلى البريد","راجع البريد غير المرغوب فيه والتبويبات الأخرى، وتأكد من البريد المكتوب حرفيًا. انتظر بضع دقائق قبل طلب رمز جديد، ولا تطلب عدة رموز متتالية.","The verification code did not arrive by email","Check spam and other inbox tabs, and confirm the exact email address. Wait a few minutes before requesting another code; avoid repeated requests."],
["وصل رمز التحقق متأخرًا وأصبح غير صالح","اطلب رمزًا جديدًا واستخدم أحدث رسالة فقط؛ غالبًا تُلغى الرموز السابقة عند إصدار رمز أحدث. لا تشارك الرمز مع أي شخص.","The verification code arrived late and expired","Request a new code and use only the latest message; earlier codes are often invalidated. Never share the code with anyone."],
["صندوق البريد لا يعرض أي رسائل جديدة","تأكد من أنك تفتح صندوق البريد الصحيح، وافحص الأرشيف والرسائل غير المرغوب فيها وسعة التخزين. حدّث الصفحة أو افتح البريد من الموقع الرسمي.","The inbox shows no new messages","Make sure you opened the correct mailbox, then check archive, spam and storage capacity. Refresh or open the mailbox through its official website."],
["وصلتني رسالة تحقق من مرسل غريب","لا تضغط على روابط الرسالة ولا تدخل بياناتك. افتح الموقع الرسمي بنفسك واطلب رمزًا جديدًا من داخله، ثم تجاهل الرسالة المشبوهة.","A verification message came from an unfamiliar sender","Do not click its links or enter your details. Open the official website yourself and request a code there, then ignore the suspicious message."],
["كتبت البريد بحرف غلط أثناء الطلب","لا تحاول تفعيل الاشتراك على بريد غير صحيح. أرسل رقم الطلب والبريد الصحيح للدعم قبل تنفيذ التفعيل حتى يتم التحقق من إمكانية التصحيح.","I entered an incorrect email during checkout","Do not activate the subscription on the wrong email. Send support your order reference and correct email before activation so they can check whether it can be corrected."],
["تسجيل Google لا يفتح نفس الحساب","اضغط اختيار حساب آخر وحدد البريد المرتبط بالاشتراك. إذا فتح المتصفح حسابًا تلقائيًا، سجّل الخروج من حساب Google غير المطلوب أو استخدم نافذة خاصة.","Google sign-in opens the wrong account","Choose another account and select the email linked to the subscription. If the browser automatically selects the wrong Google account, sign out of it or use a private window."],
["البريد ممتلئ ولا يستقبل رموزًا","احذف رسائل أو مرفقات كبيرة لم تعد تحتاجها، وأفرغ سلة المهملات إذا كانت السعة لا تزال ممتلئة. بعد توفير مساحة اطلب إرسال الرمز مرة أخرى.","The mailbox is full and cannot receive codes","Delete large messages or attachments you no longer need, and empty Trash if storage is still full. Request the code again after freeing space."],
["رابط التفعيل يقول إنه غير صالح","استخدم أحدث رسالة وافتح الرابط كاملًا في المتصفح، ولا تنسخ جزءًا منه فقط. إذا انتهت صلاحيته، ارجع إلى صفحة المزود واطلب رابطًا جديدًا.","The activation link says it is invalid","Use the latest message and open the full link in a browser. Do not copy only part of it. If it expired, return to the provider page and request a new link."],
["رسالة SMS لا تصل إلى رقم الهاتف","راجع مفتاح الدولة وصحة الرقم وإمكانية استقبال الرسائل الدولية، ثم انتظر قبل إعادة الطلب. إذا كانت الخدمة توفر وسيلة تحقق أخرى رسمية، استخدمها.","SMS verification does not reach my phone","Check the country code, phone number and ability to receive international messages, then wait before retrying. Use another official verification method if the service offers one."],
["ظهرت رسالة تجاوز عدد طلبات الرموز","توقف عن طلب الرموز وانتظر فترة التهدئة التي يحددها المزود. لا تستخدم أرقامًا أو بريدًا غير تابع لك لتجاوز الحد.","I reached the verification-code request limit","Stop requesting codes and wait for the provider’s cooldown period. Do not use phone numbers or email addresses that do not belong to you to bypass the limit."]
]);
add('activation',[
["الاشتراك المدفوع لا يظهر داخل الحساب","تأكد من الدخول بالبريد وطريقة الدخول الصحيحين، ثم راجع صفحة الاشتراك لدى المزود وسجّل الخروج والدخول مرة واحدة. أرسل رقم الطلب للدعم إذا استمر الاختلاف.","The paid subscription does not appear in the account","Sign in with the correct email and method, check the provider’s subscription page, then sign out and back in once. Contact support with the order reference if it is still missing."],
["كود التفعيل يقول إنه مستخدم بالفعل","لا تكرر إدخال الكود. صوّر الرسالة وسجّل وقت المحاولة وأرسلها مع رقم الطلب للدعم للتحقق من حالة الكود.","The activation code says it has already been used","Do not keep entering the code. Capture the message, note when you tried it and send it with your order reference to support for a status check."],
["كود التفعيل غير صالح للمنتج","راجع اسم المنتج والإصدار والبلد وطريقة التفعيل قبل إدخال الكود. بعض الأكواد مرتبطة بإصدار أو منطقة محددة؛ لا تغيّر إعدادات البلد عشوائيًا.","The activation code is not valid for this product","Check the product name, edition, country and activation method before entering the code. Some codes are tied to a specific edition or region; do not change country settings randomly."],
["حالة التفعيل ما زالت Pending","اتبع وقت المعالجة الموضح في تفاصيل الباقة، واحتفظ برقم الطلب. إذا تجاوزت المدة المعلنة، تواصل مع الدعم بدل إنشاء طلب مكرر.","Activation is still pending","Allow the processing time stated in the plan details and keep your order reference. If the stated time has passed, contact support instead of placing a duplicate order."],
["تم ربط الاشتراك ببريد غير الذي أستخدمه","راجع رسالة التسليم ونوع الباقة أولًا؛ قد تكون الباقة على حساب جاهز أو على بريدك الشخصي. إذا كان الربط غير مطابق لما طلبته، أرسل رقم الطلب للدعم قبل تغيير أي بيانات.","The subscription was linked to a different email","Check the delivery message and account type first; the plan may use a ready account or your personal email. If it differs from what you ordered, contact support before changing any details."],
["التجديد لم يحدث في موعده","راجع تاريخ التجديد وطريقة الدفع وحالة الاشتراك لدى المزود. لا تفترض أن كل الباقات تتجدد تلقائيًا؛ بعض العروض تحتاج إجراءً يدويًا أو تأكيدًا من الدعم.","The subscription did not renew on time","Check the renewal date, payment method and provider status. Do not assume every plan renews automatically; some offers require a manual step or support confirmation."],
["تاريخ الانتهاء أقرب مما توقعت","قارن تاريخ بداية الاشتراك وتاريخ الانتهاء المكتوبين في رسالة التسليم مع مدة الباقة. أرسل صورة التفاصيل للدعم إذا لم تتطابق المدة مع الوصف.","The expiry date is earlier than expected","Compare the start and expiry dates in the delivery message with the plan term. Send support a screenshot if the dates do not match the description."],
["وصلت إلى الحد الأقصى للأجهزة","افتح إعدادات الحساب وراجع الأجهزة النشطة. أزل جهازًا قديمًا إذا كانت سياسة الخدمة تسمح، ثم انتظر تحديث الحالة قبل إعادة التفعيل.","The maximum device count was reached","Open account settings and review active devices. Remove an old device if the service policy allows it, then wait for the status to update before activating again."],
["ميزة Pro لا تعمل رغم ظهور الاشتراك","راجع نوع الخطة والميزة المطلوبة والمنطقة والجهاز المستخدم؛ ليست كل المزايا متاحة في كل الخطط أو التطبيقات. حدّث التطبيق ثم أرسل لقطة الحالة للدعم.","A Pro feature does not work although the plan is visible","Check the plan type, requested feature, region and device; not every feature is available on every plan or app. Update the app and send support a screenshot of the status."],
["غيّرت كلمة مرور الحساب بعد استلامه","إذا كان الحساب جاهزًا، أوقف التعديلات الإضافية وتواصل مع الدعم لتأكيد الإجراء الصحيح وأثره على الدعم والضمان. لا ترسل كلمة المرور الجديدة أو رمز التحقق.","I changed the account password after delivery","If it is a ready account, stop making further changes and contact support to confirm the correct next step and any effect on assistance or warranty. Do not send the new password or verification code."]
]);
add('orders',[
["تم خصم المبلغ ولم يظهر رقم الطلب","احتفظ بإشعار الخصم ورقم العملية ووقت الدفع، ثم افحص صفحة الطلبات. تواصل مع الدعم بهذه البيانات قبل إعادة الدفع لتجنب تكرار الخصم.","Money was deducted but no order number appeared","Keep the payment notice, transaction reference and time, then check your orders page. Contact support with these details before paying again to avoid a duplicate charge."],
["الطلب ظاهر Pending Payment رغم التحويل","قد يحتاج التحويل الخارجي إلى مراجعة وتأكيد من الدعم. أرسل رقم الطلب ومرجع العملية عبر القناة الرسمية وانتظر تحديث الحالة؛ صورة التحويل وحدها لا تعني اكتمال التأكيد.","The order still says Pending Payment after a transfer","External transfers may need review and confirmation by support. Send the order reference and transaction ID through the official channel and wait for the status update; a screenshot alone is not final confirmation."],
["اتعمل لي طلبان لنفس الاشتراك","لا تدفع الطلبين قبل مراجعة الحالة. أرسل رقمي الطلبين للدعم ووضح أيهما تريد الاحتفاظ به حتى يتم التحقق من التكرار.","Two orders were created for the same subscription","Do not pay both orders before checking. Send support both order references and state which one you want to keep so the duplicate can be reviewed."],
["اخترت مدة أو باقة غلط قبل الدفع","ارجع إلى السلة وتأكد من اسم الخطة والمدة والكمية قبل التأكيد. إذا لم تدفع بعد، أزل الاختيار الخاطئ وأضف الباقة الصحيحة.","I selected the wrong term or plan before payment","Return to the cart and check the plan name, term and quantity before confirming. If you have not paid, remove the wrong selection and add the correct plan."],
["هل لقطة التحويل وحدها تؤكد الدفع؟","لا؛ احتفظ بالإيصال وأرسل مرجع العملية للدعم، وانتظر تأكيد وصول المبلغ وتحديث الطلب في النظام قبل اعتبار الطلب مدفوعًا.","Does a transfer screenshot alone confirm payment?","No. Keep the receipt and send the transaction reference to support. Wait for receipt confirmation and an updated order status before treating the order as paid."],
["طلب الضيف اختفى بعد إغلاق المتصفح","ارجع من نفس الجهاز والمتصفح إلى رسالة التأكيد أو صفحة المتابعة واستخدم رقم الطلب. إذا لم تجده، أرسل رقم العملية وبيانات التواصل للدعم.","A guest order disappeared after closing the browser","Return on the same device and browser to the confirmation message or tracking page and use the order reference. If you cannot find it, send the transaction reference and contact details to support."],
["كتبت رقم واتساب أو بريدًا غير صحيح","تواصل مع الدعم برقم الطلب والبيانات الصحيحة قبل التسليم. لا تنشئ طلبًا جديدًا لمجرد تصحيح وسيلة التواصل.","I entered the wrong WhatsApp number or email","Contact support with the order reference and corrected details before delivery. Do not create a new order just to correct contact information."],
["رصيد المحفظة أقل من إجمالي السلة","راجع إجمالي الطلب والخصم والرصيد المتاح. اشحن من وسائل الدفع الرسمية فقط، ثم أعد فتح السلة وتأكد من الإجمالي قبل التأكيد.","Wallet balance is lower than the cart total","Check the order total, discount and available balance. Top up only through official payment methods, then reopen the cart and confirm the total before checkout."],
["طلبت استرداد المبلغ ولم يصل بعد","راجع حالة طلب الاسترداد وسياسة المتجر وطريقة الدفع الأصلية. قد تختلف مدة ظهور المبلغ حسب البنك أو مزود الدفع؛ احتفظ برقم الطلب ومرجع الاسترداد.","My refund has not arrived yet","Check the refund status, store policy and original payment method. The time for funds to appear can vary by bank or payment provider; keep the order and refund references."],
["كود الخصم لا يعمل في السلة","تأكد من تاريخ العرض والمنتجات المشمولة والحد الأدنى والقيود على الجمع بين الخصومات. راجع الإجمالي النهائي قبل الدفع، ولا تعتمد على سعر منشور قديم.","A discount code does not work in the cart","Check the offer dates, eligible products, minimum spend and whether discounts can be combined. Review the final total before payment and do not rely on an outdated advertised price."]
]);
add('ai',[
["رصيد الكريدت أصبح صفرًا فجأة","افتح صفحة الاستخدام وتحقق من الخطة وفترة إعادة ضبط الرصيد والمهام التي استهلكته. إذا كان الرقم لا يطابق وصف الباقة، أرسل لقطة سجل الاستخدام ورقم الطلب للدعم.","AI credits suddenly show zero","Open the usage page and check the plan, reset period and tasks that consumed credits. If the balance conflicts with the plan description, send support a usage screenshot and order reference."],
["وصلت إلى حد الرسائل أو الطلبات","راجع حد الاستخدام الظاهر في الحساب وموعد إعادة ضبطه. جرّب الانتظار أو اختيار نموذج متاح ضمن خطتك؛ لا تفترض أن الاشتراك يعني استخدامًا غير محدود.","I reached a message or request limit","Check the usage limit and reset time shown in your account. Wait or choose an available model within your plan; a subscription does not necessarily mean unlimited use."],
["النموذج الذي أحتاجه غير موجود","افحص قائمة النماذج والخطة والمنطقة، ثم حدّث التطبيق أو مساحة العمل. بعض النماذج تُطرح تدريجيًا أو تتغير أسماؤها؛ استخدم بديلًا متاحًا إلى أن تتأكد من الإتاحة.","The model I need is missing","Check the model list, plan and region, then update the app or workspace. Models may roll out gradually or change names; use an available alternative while confirming availability."],
["المساعد يرد ببطء شديد","اختبر الإنترنت وابدأ محادثة جديدة بطلب أقصر، ثم جرّب مرة أخرى بعد قليل. تحقق من حالة الخدمة الرسمية إذا استمرت المشكلة على أكثر من جهاز.","The assistant responds very slowly","Test your connection and start a new chat with a shorter prompt, then retry later. Check the provider’s official status if the issue persists across devices."],
["الإجابة تبدو واثقة لكنها خاطئة","اطلب توضيح الافتراضات ومصادر كل معلومة، ثم راجع المصادر الأصلية. لا تعتمد على الإجابة وحدها في قرار طبي أو مالي أو قانوني أو أكاديمي مهم.","The answer sounds confident but is wrong","Ask it to state assumptions and sources, then verify original references. Do not rely on the answer alone for important medical, financial, legal or academic decisions."],
["رفع ملف PDF أو Excel مرفوض","تحقق من حجم الملف وصيغته وحدود الخطة، وأزل الحماية بكلمة مرور إذا كان الملف ملكك ومسموحًا لك. جرّب تقسيم الملف أو حفظ نسخة أبسط.","A PDF or Excel upload is rejected","Check file size, format and plan limits. Remove password protection only if you own the file and are allowed to do so. Try splitting it or saving a simpler copy."],
["تحليل الصور غير متاح في المحادثة","تأكد من اختيار النموذج أو الواجهة التي تدعم الصور، ومن أن نوع الملف وحجمه مقبولان. أعد فتح محادثة جديدة إذا استمر تعطل الرفع.","Image analysis is unavailable in chat","Choose a model or interface that supports images and check accepted file type and size. Start a new chat if upload remains unavailable."],
["سجل المحادثات اختفى","تأكد من الحساب الصحيح وافحص الأرشيف وإعدادات سجل المحادثات. حدّث الصفحة وافتح الخدمة من متصفح آخر؛ لا تحذف بيانات المتصفح قبل التأكد من مزامنة ما تحتاجه.","Chat history has disappeared","Check the correct account, archive and chat-history settings. Refresh and try another browser; do not clear browser data before confirming anything important is synced."],
["البحث لا يعرض روابط أو مصادر","فعّل وضع البحث أو التصفح إذا كان متاحًا، واكتب سؤالًا يتطلب معلومات حديثة. افتح الروابط الناتجة بنفسك وتأكد من تاريخها ومصدرها.","Search does not show links or sources","Enable search or browsing mode if available and ask a question that needs current information. Open the resulting links yourself and check their date and source."],
["اشتراك الموقع لا يشمل رصيد API","راجع وصف الباقة ولوحة الفوترة؛ استخدام API قد يُحاسب بصورة منفصلة عن اشتراك واجهة الموقع. لا تضع مفتاح API في المتصفح أو ترسله في محادثة عامة.","The website plan does not include API credits","Check the plan description and billing dashboard; API usage may be billed separately from the website subscription. Never put an API key in browser code or share it publicly."]
]);
add('media',[
["توليد الفيديو عالق على Processing","راجع سجل المهمة وانتظر الوقت المعتاد الذي تعرضه الخدمة. افحص اتصال الإنترنت وحجم الطلب، ولا تنشئ نسخة ثانية قبل التأكد من حالة المهمة الأولى.","Video generation is stuck on Processing","Check task history and allow the processing time shown by the service. Check connectivity and input size, and do not create a duplicate until the first task status is clear."],
["تم خصم رصيد ولم يظهر الفيديو","احفظ رقم المهمة ووقت الإنشاء وصورة الرصيد، ثم افحص سجل النتائج والتنزيلات. لا تكرر التوليد فورًا؛ أرسل البيانات للدعم إذا لم يظهر الملف بعد تحديث الحالة.","Credits were deducted but no video appeared","Save the task ID, creation time and balance screenshot, then check generation history and downloads. Do not immediately regenerate; contact support if the file is still missing after status refresh."],
["طلب إنشاء صورة تم رفضه","راجع رسالة الرفض وأزل التفاصيل التي قد تخالف قواعد الخدمة. استخدم وصفًا بديلًا مسموحًا، ولا تحاول تجاوز ضوابط السلامة أو حقوق الأشخاص.","An image-generation request was rejected","Review the rejection notice and remove details that may violate service rules. Use an allowed alternative prompt; do not bypass safety controls or people’s rights."],
["جودة التصدير أقل من المطلوب","اختر الدقة ومعدل الإطارات ونسبة الأبعاد قبل التصدير، وتأكد من أن المصدر الأصلي يدعمها. جرّب مقطعًا قصيرًا قبل إخراج المشروع كاملًا.","Export quality is lower than expected","Set resolution, frame rate and aspect ratio before export, and confirm the source supports them. Test a short clip before exporting the full project."],
["ظهر Watermark على الملف النهائي","راجع خطة الاشتراك وخيارات التصدير وحقوق العنصر المستخدم. بعض القوالب أو الأصول لها شروط منفصلة؛ لا تحاول إزالة علامة مائية تخص طرفًا آخر دون حق.","A watermark appeared on the final file","Check the plan, export options and licence for the asset used. Some templates or assets have separate terms; do not remove another party’s watermark without rights."],
["الصوت الناتج لا يشبه العينة","تأكد من اختيار الصوت واللغة واللهجة الصحيحة، واكتب الأسماء بعلامات ترقيم واضحة. جرّب عينة قصيرة وإعدادات سرعة ونبرة مختلفة ضمن الخيارات المتاحة.","Generated speech does not sound like the sample","Select the correct voice, language and accent, and punctuate names clearly. Test a short sample and adjust speed or tone using available settings."],
["مزامنة حركة الشفاه مع الصوت غير دقيقة","استخدم صوتًا واضحًا بلغة مناسبة للمقطع، وتأكد من تطابق مدة الصوت والفيديو. قلّل الضوضاء وقسّم المقاطع الطويلة إذا كانت الأداة تدعم ذلك.","Lip sync does not match the audio","Use clear audio in a language supported by the clip and match audio and video duration. Reduce noise and split long clips if the tool supports it."],
["رفع فيديو من الهاتف يفشل","تحقق من الصيغة والترميز والحجم والمدة المدعومة، ثم جرّب تحويل نسخة إلى MP4 بترميز شائع. احتفظ بالملف الأصلي ولا تستخدم مواقع تحويل غير موثوقة للملفات الخاصة.","A phone video upload fails","Check supported format, codec, size and duration, then try an MP4 copy with a common codec. Keep the original and avoid untrusted converters for private files."],
["الفيديو النهائي دقته منخفضة","راجع إعدادات التصدير وخيار الجودة قبل بدء المعالجة، وتأكد من أن الخطة تسمح بالدقة المطلوبة. تكبير فيديو منخفض الدقة لا يعيد تفاصيل لم تكن موجودة.","The final video has low resolution","Check export quality settings before processing and confirm the plan supports the required resolution. Upscaling a low-resolution video cannot restore missing detail."],
["الفيديو تم تصديره بدون صوت","تأكد من تفعيل مسار الصوت ومستوى الصوت وعدم كتم المقطع أو الجهاز. افتح الملف في مشغل آخر واختبر الصوت قبل إعادة التصدير.","The video exported without sound","Check that the audio track is enabled, volume is up and neither the clip nor device is muted. Open the file in another player and test before exporting again."]
]);
add('design',[
["عناصر Pro ما زالت مقفولة","تأكد من الحساب والفريق الصحيحين ومن حالة الخطة داخل صفحة الحساب. قد تكون بعض العناصر منفصلة أو مرتبطة بمستوى عضوية مختلف.","Pro elements are still locked","Check the correct account and team and confirm plan status in account settings. Some assets may be separate or tied to a different membership tier."],
["الخط المستخدم غير موجود عند التصدير","تحقق من تثبيت الخط وترخيص استخدامه، أو استبدله بخط متاح داخل التطبيق. افتح الملف على الجهاز نفسه الذي ستصدر منه النسخة النهائية.","The chosen font is missing on export","Check that the font is installed and licensed for use, or replace it with an in-app font. Open the file on the device you will use for final export."],
["المشروع لا يتزامن بين الكمبيوتر والهاتف","تأكد من استخدام نفس الحساب ومساحة العمل، واترك المزامنة تكتمل على اتصال ثابت. تجنب تعديل نسخة غير متصلة على جهازين في الوقت نفسه.","The project does not sync between computer and phone","Use the same account and workspace, and allow sync to finish on a stable connection. Avoid editing offline copies on two devices at the same time."],
["تصدير PNG بخلفية شفافة لا يعمل","اختر PNG وتأكد من تفعيل خيار الخلفية الشفافة إن كان متاحًا في الخطة. بعض الصيغ مثل JPG لا تدعم الشفافية.","Transparent PNG export does not work","Choose PNG and enable the transparent-background option if available in your plan. Formats such as JPG do not support transparency."],
["ملف التصميم لا يفتح على جهاز آخر","راجع صيغة الملف وإصدار البرنامج والخطوط المستخدمة. جرّب تصدير نسخة PDF أو صورة للمشاركة، واحتفظ بالملف الأصلي القابل للتعديل.","The design file will not open on another device","Check the file format, app version and fonts used. Export a PDF or image for sharing and keep the original editable file."],
["رابط التصميم المشترك يقول Access Denied","تأكد من أنك سجلت الدخول بالحساب المدعو، واطلب من المالك مراجعة صلاحيات الرابط والفريق. لا تطلب كلمة مرور المالك لمشاهدة الملف.","A shared design link says Access Denied","Sign in with the invited account and ask the owner to review link and team permissions. Do not request the owner’s password to view the file."],
["القوالب لا تحمل داخل التطبيق","حدّث التطبيق وافحص الاتصال، ثم جرّب فتح القالب من المتصفح الرسمي. امسح ذاكرة التخزين المؤقت فقط إذا لم تفقد ملفات محلية غير متزامنة.","Templates will not load in the app","Update the app and check connectivity, then try opening the template in the official browser. Clear cache only after confirming no unsynced local files could be lost."],
["الألوان تختلف بعد التصدير","راجع نمط الألوان وملف ICC وإعدادات الشاشة، وصدّر عينة صغيرة للمقارنة. قد تختلف الألوان بين الشاشة والطباعة بسبب إدارة الألوان.","Colours change after export","Check colour mode, ICC profile and display settings, then export a small sample for comparison. Screen and print colours can differ because of colour management."],
["دعوة الفريق لم تصل إلى زميلي","تأكد من البريد الصحيح واطلب منه فحص Spam. أعد إرسال الدعوة من لوحة الفريق وتحقق من وجود مقعد متاح في الخطة.","A team invitation did not reach my colleague","Confirm the correct email and ask them to check Spam. Resend the invitation from team settings and check that the plan has an available seat."],
["تطبيق التصميم يغلق فجأة","حدّث التطبيق ونظام التشغيل، وأعد تشغيل الجهاز وتحقق من المساحة والذاكرة. جرّب فتح مشروع آخر؛ إذا كانت المشكلة في ملف واحد فقط احتفظ بنسخة منه.","The design app closes unexpectedly","Update the app and operating system, restart the device and check storage and memory. Try another project; if only one file is affected, keep a copy of it."]
]);
add('education',[
["المقرر مقفول رغم وجود اشتراك","تأكد من الالتحاق بالمقرر بالحساب الصحيح، ومن أن المقرر ضمن الخطة وليس شراءً منفصلًا. راجع المتطلبات السابقة أو تاريخ إتاحة المحتوى.","A course is locked despite an active subscription","Confirm enrollment with the correct account and that the course is included rather than sold separately. Check prerequisites and content availability dates."],
["الشهادة لم تظهر بعد انتهاء الدروس","راجع متطلبات الشهادة والاختبارات والواجبات ونسبة الإكمال. تأكد أن وضع التسجيل أو المشاهدة الذي تستخدمه مؤهل للشهادة حسب شروط المنصة.","The certificate did not appear after lessons ended","Review certificate requirements, quizzes, assignments and completion percentage. Confirm your enrollment or audit mode is eligible for a certificate under platform rules."],
["نسبة التقدم لا تتحدث","أكمل الدرس حتى نهايته وانتظر ظهور علامة الإكمال، ثم حدّث الصفحة. تأكد من الاتصال بالحساب نفسه وعدم الانتقال بين أكثر من جهاز أثناء الحفظ.","Course progress does not update","Finish the lesson, wait for the completion mark and refresh. Make sure you are using the same account and not switching devices while progress is saving."],
["فيديو الدورة لا يعمل","حدّث المتصفح أو التطبيق، وخفّض جودة الفيديو واختبر شبكة أخرى. افحص إعدادات الصوت وحظر التشغيل التلقائي، ثم جرّب درسًا آخر.","The course video will not play","Update the browser or app, lower video quality and test another network. Check audio and autoplay settings, then try another lesson."],
["الترجمة العربية غير موجودة","افتح قائمة اللغات والترجمة في مشغل الفيديو. إذا لم تظهر العربية ضمن المسارات المتاحة، فقد لا توفرها الدورة؛ لا يمكن إضافتها من إعدادات الحساب وحدها.","Arabic subtitles are missing","Open the language and subtitle menu in the player. If Arabic is not listed, the course may not provide it; account settings alone cannot add a missing subtitle track."],
["الاختبار لا يقبل الإجابة","راجع صيغة الإجابة المطلوبة والحقول الإلزامية والوقت المتبقي. احفظ ما كتبته إن أمكن، ثم أعد الإرسال مرة واحدة وتأكد من ظهور رسالة النجاح.","The quiz will not accept my answer","Check the required answer format, mandatory fields and remaining time. Save your work if possible, submit once more and confirm a success message appears."],
["سجلت في الدورة بالبريد الخطأ","سجّل الخروج وافتح الحساب الذي يحتوي على التسجيل الصحيح. إذا تم الشراء بالفعل على بريد غير صحيح، تواصل مع دعم المنصة والمتجر قبل محاولة نقل التسجيل.","I enrolled using the wrong email","Sign out and open the account containing the correct enrollment. If a purchase was made on the wrong email, contact the platform and store support before attempting to transfer it."],
["انتهى الوصول قبل إكمال الدورة","راجع تاريخ بداية ونهاية الباقة ونوع الوصول المقدم؛ بعض الاشتراكات لها مدة محددة ولا تعني وصولًا دائمًا. أرسل تفاصيل الطلب للدعم إذا كان الانتهاء لا يطابق المدة المعلنة.","Course access ended before I finished","Check the plan start and end dates and the access type; some subscriptions have a fixed term and do not provide lifetime access. Contact support if the expiry does not match the stated term."],
["تطبيق الهاتف لا يعرض نفس التقدم","تأكد من الحساب نفسه واتصال الإنترنت، ثم اسحب للتحديث أو سجّل الخروج والدخول. انتظر اكتمال المزامنة قبل متابعة الدرس على جهاز آخر.","The mobile app shows different progress","Confirm the same account and internet connection, then refresh or sign out and back in. Allow sync to finish before continuing on another device."],
["المحتوى الذي نزلته لا يعمل بدون إنترنت","تحقق من أن المنصة تدعم التنزيل دون اتصال وأن الملف ما زال داخل مدة الصلاحية. قد تتطلب بعض التطبيقات فتح المحتوى من داخل التطبيق الرسمي.","Downloaded content does not work offline","Check that offline downloads are supported and the file is still within its validity period. Some platforms require content to be opened inside the official app."]
]);
add('productivity',[
["Word أو Excel يطلبان تفعيلًا من جديد","افتح التطبيق وسجّل الدخول بالحساب المرتبط بالترخيص، ثم راجع صفحة الحساب وحالة الاشتراك. تأكد من أن نسخة Office متوافقة مع نوع الترخيص.","Word or Excel asks for activation again","Open the app and sign in with the licensed account, then check the account page and subscription status. Confirm the Office edition is compatible with the licence."],
["الملفات لا تتزامن مع التخزين السحابي","افحص الإنترنت والمساحة المتاحة وحالة المزامنة، ثم أعد تشغيل التطبيق. لا تحذف الملفات المحلية قبل التأكد من وجود نسخة سحابية مكتملة.","Files do not sync to cloud storage","Check internet, available storage and sync status, then restart the app. Do not delete local files until a complete cloud copy is confirmed."],
["مساحة التخزين السحابي ممتلئة","راجع الملفات الكبيرة والنسخ الاحتياطية وسلة المحذوفات، ثم احذف ما لم تعد تحتاجه بعد حفظ نسخة. تحقق من سعة الخطة الفعلية بدل افتراض سعة غير مذكورة.","Cloud storage is full","Review large files, backups and Trash, then remove items you no longer need after keeping a copy. Check the actual plan allowance rather than assuming an unlisted capacity."],
["مشاركة الملف لا تسمح للمستلم بفتحه","راجع إعدادات الرابط وصلاحية العرض أو التحرير والبريد المسموح له. أرسل رابطًا جديدًا بعد ضبط الأذونات، ولا تجعل الملف عامًا إذا كان يحتوي على بيانات خاصة.","The recipient cannot open a shared file","Check link settings, viewer or editor permissions and allowed email addresses. Send a new link after adjusting access; do not make private files public."],
["تصدير PDF يغيّر ترتيب الصفحات","راجع حجم الورق والهوامش وفواصل الصفحات والخطوط المضمنة، ثم صدّر نسخة تجريبية. افتح PDF في قارئ مختلف قبل إرساله.","PDF export changes page layout","Check paper size, margins, page breaks and embedded fonts, then export a test copy. Open the PDF in another reader before sending it."],
["تطبيق الكمبيوتر يقول إن الترخيص غير موجود","تأكد من البريد المستخدم داخل التطبيق ومن حالة الترخيص في صفحة الحساب. أعد تشغيل التطبيق بعد تسجيل الدخول، ولا تدخل مفاتيحًا من مصادر غير موثوقة.","The desktop app says no licence is found","Check the email used in the app and licence status on the account page. Restart after signing in and do not enter keys from untrusted sources."],
["نسخة التطبيق غير متوافقة مع جهازي","راجع متطلبات النظام والإصدار المطلوب من موقع المزود الرسمي. حدّث النظام إن كان مدعومًا أو استخدم نسخة متوافقة؛ لا تثبت ملفات تنفيذية مجهولة.","The app version is incompatible with my device","Check system requirements and supported versions on the provider’s official website. Update the OS if supported or use a compatible version; avoid unknown installers."],
["الملاحظات أو الصفحات لا تظهر في مساحة العمل","تحقق من مساحة العمل والفريق والفلاتر والأرشيف، ثم ابحث بالعنوان. اطلب من مالك المساحة مراجعة صلاحياتك إذا كان المحتوى تابعًا لفريق آخر.","Notes or pages are missing from the workspace","Check the workspace, team, filters and archive, then search by title. Ask the workspace owner to review your permissions if the content belongs to another team."],
["ظهرت نسخ مكررة من نفس الملف","قارن تاريخ التعديل ومكان الحفظ قبل حذف أي نسخة. اختر نسخة رئيسية، وانقل التعديلات المهمة إليها، ثم راجع المزامنة لتجنب تكرار الملفات مرة أخرى.","Duplicate copies of the same file appeared","Compare modification dates and storage locations before deleting anything. Choose a primary copy, move important changes into it and review sync settings to prevent more duplicates."],
["التكامل مع تطبيق آخر توقف","راجع صلاحيات الربط وتاريخ انتهاء التفويض، ثم افصل التكامل وأعد ربطه من صفحة المزود الرسمية. لا تمنح تطبيقًا غير معروف صلاحيات أوسع من المطلوب.","An integration with another app stopped working","Check connection permissions and authorization expiry, then reconnect it from the provider’s official page. Do not grant an unknown app broader permissions than needed."]
]);
add('iptv',[
["قائمة IPTV لا يتم تحميلها","تأكد من اتصال الإنترنت ومن نسخ رابط السيرفر كاملًا. اختر طريقة Xtream أو M3U المطابقة للبيانات المستلمة، ثم حدّث القائمة مرة واحدة.","The IPTV playlist will not load","Check internet access and copy the full server URL. Choose the Xtream or M3U method matching the supplied details, then refresh the playlist once."],
["اسم المستخدم أو كلمة المرور غير صحيحين","انسخ البيانات كما وصلتك دون مسافات أو رموز زائدة، وتأكد من وضع كل قيمة في خانتها الصحيحة. راجع تاريخ انتهاء الاشتراك إذا استمر الرفض.","The username or password is incorrect","Copy the supplied details without extra spaces or characters and place each value in the correct field. Check subscription expiry if access is still rejected."],
["التطبيق يعرض Server Timeout","اختبر الإنترنت من تطبيق آخر، ثم أعد تشغيل التطبيق والراوتر. إذا كانت كل القنوات لا تعمل على أكثر من شبكة، أرسل رسالة الخطأ ووقت حدوثها للدعم.","The app displays Server Timeout","Test internet access in another app, then restart the player and router. If all channels fail on more than one network, send support the error and time it occurred."],
["بعض القنوات تعرض شاشة سوداء","حدّث قائمة القنوات وجرب قناة أخرى. قد يكون مصدر القناة متوقفًا مؤقتًا؛ سجّل اسم القناة والوقت ولا تغيّر بيانات السيرفر من نفسك.","Some channels show a black screen","Refresh the channel list and test another channel. The channel source may be temporarily unavailable; note its name and time and do not change server details yourself."],
["البث يقطع باستمرار","استخدم اتصالًا سلكيًا إن أمكن، وأوقف التنزيلات الأخرى، وجرّب جودة أقل. اختبر السرعة والثبات في أوقات مختلفة؛ سرعة الذروة وحدها لا تضمن بثًا مستقرًا.","Streaming keeps buffering","Use Ethernet if possible, pause other downloads and try lower quality. Test speed and stability at different times; peak speed alone does not guarantee stable streaming."],
["دليل البرامج لا يعرض مواعيد","حدّث EPG من إعدادات التطبيق وتأكد من المنطقة الزمنية. ليست كل القنوات توفر بيانات جدول البرامج؛ غياب الدليل لا يعني بالضرورة انتهاء الاشتراك.","The programme guide shows no schedule","Refresh EPG in the player settings and check the time zone. Not every channel provides programme data; a missing guide does not necessarily mean the subscription expired."],
["الاشتراك يعمل على جهاز واحد فقط","راجع عدد الأجهزة والجلسات المتزامنة المسموحة في الباقة. سجّل الخروج من جهاز قديم إذا كان مسموحًا، ولا تشارك بيانات الدخول خارج شروط الخدمة.","The subscription works on only one device","Check the plan’s allowed devices and simultaneous sessions. Sign out of an old device if permitted, and do not share credentials outside the service terms."],
["التطبيق يقول إن صيغة القائمة غير صحيحة","تأكد أنك تستخدم نوع القائمة الصحيح وأن الرابط غير مقطوع أو منتهي. أدخل بيانات Xtream في حقولها المنفصلة إذا كانت هذه هي الطريقة المرسلة لك.","The app says the playlist format is invalid","Confirm the correct playlist type and that the URL is complete and current. Enter Xtream details in their separate fields if that is the method provided."],
["تطبيق التلفزيون غير متوافق مع نظام الشاشة","راجع متجر التطبيقات الخاص بنظام الشاشة وإصدار النظام. إذا لم يتوفر التطبيق رسميًا، استخدم جهاز تشغيل خارجيًا متوافقًا بدل محاولة تثبيت ملف غير مدعوم.","The TV app is incompatible with the television OS","Check the TV’s official app store and OS version. If the app is not officially available, use a compatible external streaming device rather than forcing an unsupported installer."],
["قنوات كانت موجودة ثم اختفت","حدّث قائمة القنوات وأعد تشغيل التطبيق، وتحقق من التصنيف أو الفلاتر. إذا اختفت القنوات كلها، أرسل لقطة للقائمة ورقم الطلب للدعم.","Channels that used to appear have disappeared","Refresh the playlist and restart the app, then check categories and filters. If all channels are gone, send support a screenshot and order reference."]
]);
add('security',[
["VPN لا يتصل بأي خادم","اختر خادمًا قريبًا وبروتوكولًا آخر متاحًا، وتأكد من التاريخ والوقت. أوقف أي VPN أو Proxy متعارض واختبر شبكة أخرى.","VPN cannot connect to any server","Choose a nearby server and another available protocol, and check date and time. Disable conflicting VPN or proxy settings and test another network."],
["VPN متصل لكن لا يوجد إنترنت","افصل الاتصال وأعده، ثم جرّب خادمًا آخر. راجع إعداد DNS وKill Switch وأعد الإعدادات الافتراضية إذا لم تكن متأكدًا منها.","VPN connects but there is no internet","Disconnect and reconnect, then try another server. Check DNS and Kill Switch settings, restoring defaults if you are unsure what they do."],
["سرعة الإنترنت بطيئة مع VPN","جرّب خادمًا أقرب وأوقف التحويلات الثقيلة، واختبر بروتوكولًا آخر من داخل التطبيق. بعض الانخفاض في السرعة طبيعي بسبب التشفير والمسافة.","Internet is slow while using VPN","Try a closer server, pause heavy downloads and test another in-app protocol. Some speed reduction is normal due to encryption and server distance."],
["الموقع ما زال يعرف موقعي الجغرافي","راجع صلاحيات الموقع وملفات تعريف الارتباط وبيانات الحساب. خدمات كثيرة تستخدم أكثر من إشارة للموقع، وVPN لا يضمن تغيير المنطقة أو تجاوز قيود الخدمة.","A website still detects my location","Review location permissions, cookies and account details. Services use multiple location signals, and a VPN does not guarantee a region change or bypass of service restrictions."],
["برنامج مكافحة الفيروسات يرفض التثبيت","تأكد من متطلبات النظام وأزل برامج الحماية المتعارضة بالطريقة الرسمية قبل المحاولة. نزّل البرنامج من موقع الشركة فقط.","Antivirus software refuses to install","Check system requirements and remove conflicting security software using its official uninstall process. Download only from the vendor’s website."],
["كود الحماية يقول إنه مستخدم","لا تحاول تفعيله مرات كثيرة. راجع الحساب والأجهزة المرتبطة، ثم أرسل رسالة الخطأ ورقم الطلب للدعم للتحقق من حالة الترخيص.","Security activation code says it is used","Do not keep retrying. Check the linked account and devices, then send support the error and order reference to verify the licence."],
["برنامج الحماية حظر ملفًا أحتاجه","لا توقف الحماية بالكامل ولا تستعد الملف مباشرة. تحقق من مصدر الملف وتوقيعه، ثم أرسل بلاغًا رسميًا للشركة إذا كنت تعتقد أنه إنذار خاطئ.","Security software blocked a file I need","Do not disable protection entirely or restore the file immediately. Verify its source and signature, then submit an official false-positive report if appropriate."],
["الحماية الفورية لا تعمل","أعد تشغيل الجهاز وحدّث البرنامج، وتأكد من عدم وجود برنامج حماية آخر يتعارض معه. راجع حالة الترخيص والتنبيهات في لوحة التحكم.","Real-time protection is not working","Restart the device and update the app. Check for conflicting security software, then review licence status and alerts in the dashboard."],
["التجديد التلقائي غير واضح","راجع إعدادات الفوترة لدى المزود وتاريخ انتهاء الخطة وطريقة الدفع. لا تفترض أن التجديد التلقائي مفعل؛ ألغِه أو فعّله فقط من صفحة الحساب الرسمية.","Automatic renewal is unclear","Check provider billing settings, plan expiry and payment method. Do not assume auto-renewal is enabled; change it only through the official account page."],
["فحص الجهاز لا يكتمل","حدّث قاعدة بيانات الحماية، وأعد تشغيل الجهاز، ثم نفّذ فحصًا سريعًا قبل الكامل. إذا تكرر الخطأ، احتفظ برمز الخطأ وسجل الفحص وأرسله للدعم الرسمي.","A device scan will not finish","Update security definitions, restart and run a quick scan before a full one. If the error repeats, keep the code and scan log for official support."]
]);
add('windows-dev',[
["مفتاح Windows لا يطابق Home أو Pro","افتح الإعدادات ثم النظام ثم حول لمعرفة النسخة المثبتة. يجب أن يطابق المفتاح الإصدار والنسخة؛ لا تغيّر نسخة النظام عشوائيًا.","The Windows key does not match Home or Pro","Open Settings, System and About to identify the installed edition. The key must match the release and edition; do not change editions randomly."],
["Windows يعرض خطأ في التنشيط","تأكد من الإنترنت والتاريخ والوقت، ثم افتح إعدادات التنشيط وشغّل مستكشف الأخطاء إن توفر. احتفظ برمز الخطأ كاملًا قبل التواصل مع الدعم.","Windows displays an activation error","Check internet, date and time, then open Activation settings and run the troubleshooter if available. Keep the full error code before contacting support."],
["فقد Windows التنشيط بعد تغيير الجهاز","استخدم مستكشف التنشيط وسجّل الدخول بحساب Microsoft المرتبط بالرخصة الرقمية إذا كان ذلك ينطبق. قابلية نقل الترخيص تختلف حسب نوعه؛ راجع شروطه مع الدعم.","Windows lost activation after a hardware change","Use the Activation troubleshooter and sign in with the Microsoft account linked to the digital licence if applicable. Transfer rights vary by licence type; check its terms with support."],
["تحديث Windows متوقف عند نسبة معينة","تحقق من المساحة والإنترنت، واحفظ عملك ثم أعد التشغيل عند طلب النظام. استخدم أداة استكشاف أخطاء Windows Update الرسمية ولا تحذف ملفات النظام يدويًا.","Windows Update is stuck at a percentage","Check storage and internet, save your work and restart when prompted. Use the official Windows Update troubleshooter and do not manually delete system files."],
["الدومين لا يشير إلى الموقع","قارن سجلات DNS المطلوبة مع السجلات الحالية لدى مسجل النطاق. غيّر السجل المطلوب فقط، وانتظر الانتشار ثم اختبر من شبكة أخرى.","The domain does not point to the website","Compare required DNS records with the current records at the domain registrar. Change only the necessary record, allow propagation and test from another network."],
["شهادة SSL لم تصدر بعد","تأكد من أن الدومين يشير إلى المشروع الصحيح وأن سجلات DNS اكتملت. أعد التحقق من لوحة الاستضافة وانتظر إصدار الشهادة؛ لا تشارك المفاتيح الخاصة.","The SSL certificate has not been issued","Confirm the domain points to the correct project and DNS has propagated. Recheck the hosting dashboard and allow certificate issuance; never share private keys."],
["عملية Build فشلت في النشر","اقرأ أول خطأ حقيقي في سجل البناء، ثم راجع الحزم ونسخة Node ومتغيرات البيئة. اختبر البناء محليًا قبل إعادة النشر.","The deployment build failed","Read the first actual build error, then check dependencies, Node version and environment variables. Test the build locally before redeploying."],
["مفتاح API يرجع Unauthorized","تأكد من المفتاح والمشروع والصلاحيات وعدم وجود مسافات زائدة. إذا ظهر المفتاح في لقطة أو مستودع عام، ألغِه وأنشئ بديلًا وخزّنه في متغيرات بيئة آمنة.","An API key returns Unauthorized","Check the key, project, permissions and extra spaces. If it appeared in a screenshot or public repository, revoke it, create a replacement and store it in secure environment variables."],
["الموقع لا يظهر رغم نجاح النشر","راجع أن حالة النشر Ready وأن الدومين مرتبط بالمشروع والفرع الصحيحين. افتح رابط النشر المباشر ثم امسح Cache المتصفح إذا كان يعرض نسخة قديمة.","The site does not appear although deployment succeeded","Confirm the deployment is Ready and the domain is linked to the correct project and branch. Open the deployment URL directly, then clear browser cache if it shows an old version."],
["استهلاك API أو الخدمة وصل إلى الحد","راجع Usage وBilling والحدود في لوحة المزود؛ قد تكون فوترة API منفصلة عن اشتراك التطبيق. لا ترفع الحد أو تضف وسيلة دفع قبل فهم التكلفة المتوقعة.","API or service usage reached its limit","Check Usage, Billing and limits in the provider dashboard; API billing may be separate from the app subscription. Do not raise limits or add payment details before understanding the expected cost."]
]);
const categories=[
 ['all','كل المشاكل','All issues'],
 ['account','الحساب وتسجيل الدخول','Account & sign-in'],
 ['email','البريد ورموز التحقق','Email & verification'],
 ['activation','التفعيل والاشتراك','Activation & subscription'],
 ['orders','الطلبات والدفع','Orders & payment'],
 ['ai','أدوات الذكاء الاصطناعي','AI tools'],
 ['media','الصورة والفيديو والصوت','Image, video & audio'],
 ['design','التصميم والتصدير','Design & export'],
 ['education','التعليم والكورسات','Education & courses'],
 ['productivity','العمل والملفات والتخزين','Productivity & files'],
 ['iptv','IPTV والبث','IPTV & streaming'],
 ['security','VPN والحماية','VPN & security'],
 ['windows-dev','Windows والبرمجة والاستضافة','Windows, development & hosting']
];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normal=v=>String(v??'').toLowerCase().normalize('NFKD').replace(/[\u064B-\u065F\u0670]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه');
function mount(doc){
 const host=doc.getElementById('commonProblemsApp');if(!host)return;
 let query='',category='all',opened=null;
 const products=(global.MasterCatalog?.products||[]).filter(p=>!p.redirectTo);
 const lang=()=>global.MasterLocale?.getState().language==='en';
 const t=(ar,en)=>lang()?en:ar;
 function filtered(){const q=normal(query.trim());return problems.filter(p=>(category==='all'||p.category===category)&&(!q||normal([p.question,p.answer,p.questionEn,p.answerEn].join(' ')).includes(q)));}
 function update(){
  const en=lang(),rows=filtered(),list=host.querySelector('.common-problem-list');
  host.querySelector('.common-problem-count').textContent=(en?rows.length+' of '+problems.length+' solutions':rows.length+' من '+problems.length+' حل');
  host.querySelectorAll('[data-problem-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.problemCategory===category)));
  list.innerHTML=rows.length?rows.map(p=>'<details class="common-problem-item" data-problem-id="'+p.id+'" '+(opened===p.id?'open':'')+'><summary><span class="common-problem-number">'+String(p.id).padStart(3,'0')+'</span><strong>'+esc(en?p.questionEn:p.question)+'</strong><span class="common-problem-chevron" aria-hidden="true">⌄</span></summary><div class="common-problem-answer"><b>'+(en?'Suggested solution':'الحل المقترح')+'</b><p>'+esc(en?p.answerEn:p.answer)+'</p><small>'+(en?'Category: ':'التصنيف: ')+esc(categories.find(c=>c[0]===p.category)?.[en?2:1]||'')+'</small></div></details>').join(''):'<div class="common-problem-empty"><strong>'+t('ملقيناش مشكلة مطابقة','No matching issue found')+'</strong><p>'+t('جرّب كلمة أبسط أو اختار تصنيفًا تاني.','Try a simpler search or choose another category.')+'</p><button type="button" data-problem-reset>'+t('عرض كل الحلول','Show all solutions')+'</button></div>';
  list.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open){opened=Number(d.dataset.problemId);list.querySelectorAll('details[open]').forEach(x=>{if(x!==d)x.open=false;});}else if(opened===Number(d.dataset.problemId))opened=null;}));
  list.querySelector('[data-problem-reset]')?.addEventListener('click',()=>{query='';category='all';opened=null;host.querySelector('#commonProblemSearch').value='';update();});
 }
 function render(){
  const en=lang(),selectOptions=products.map(p=>'<option value="'+esc(p.id)+'">'+esc(en?(p.nameEn||p.name):p.name)+'</option>').join('');
  host.innerHTML='<section class="common-problem-hero"><span class="common-problem-eyebrow">MASTER STORE · '+t('مركز الدعم الفني','SUPPORT CENTER')+'</span><div class="common-problem-hero-grid"><div><h1>'+t('حل المشكلة يبدأ من هنا.','Find the fix, step by step.')+'</h1><p>'+t('دليل عملي يضم أكثر من 120 مشكلة وحلًا لاستخدام الاشتراكات الرقمية، من تسجيل الدخول والتفعيل إلى الكريدت والفيديو وIPTV والتطبيقات.','A practical library of 120+ fixes for digital subscriptions, from sign-in and activation to credits, video, IPTV and apps.')+'</p><div class="common-problem-stats"><strong>'+problems.length+'+</strong><span>'+t('مشكلة وحل قابلين للبحث','searchable issues and solutions')+'</span></div></div><div class="common-problem-hero-card"><span aria-hidden="true">✓</span><b>'+t('ابدأ بالحل الآمن','Start with safe checks')+'</b><p>'+t('لا تشارك كلمة المرور أو رمز التحقق. ولا تغيّر بيانات الحساب الجاهز قبل الرجوع لتعليمات الباقة والدعم.','Never share passwords or verification codes. Do not change ready-account details before checking plan instructions and contacting support.')+'</p></div></div></section><section class="common-problem-explorer" aria-labelledby="commonProblemTitle"><div class="common-problem-section-heading"><div><span>'+t('ابحث في قاعدة الحلول','SEARCH THE SOLUTION LIBRARY')+'</span><h2 id="commonProblemTitle">'+t('إيه المشكلة اللي بتواجهك؟','What problem are you facing?')+'</h2></div><b class="common-problem-count" aria-live="polite"></b></div><label class="common-problem-search"><span aria-hidden="true">⌕</span><input id="commonProblemSearch" type="search" autocomplete="off" placeholder="'+t('اكتب المشكلة أو رسالة الخطأ أو اسم التطبيق…','Search an issue, error message or app…')+'" aria-label="'+t('ابحث في المشاكل والحلول','Search problems and solutions')+'"></label><div class="common-problem-categories" role="group" aria-label="'+t('تصنيفات المشاكل','Problem categories')+'">'+categories.map(c=>'<button type="button" data-problem-category="'+c[0]+'" aria-pressed="'+(c[0]===category)+'">'+(en?c[2]:c[1])+'</button>').join('')+'</div><div class="common-problem-list"></div></section><section class="common-problem-product"><div><span>'+t('دعم حسب الاشتراك','PRODUCT-SPECIFIC HELP')+'</span><h2>'+t('عايز حلول خاصة باشتراك معين؟','Need help with a specific subscription?')+'</h2><p>'+t('افتح صفحة الاشتراك للوصول إلى مشاكل وحلول مخصصة لطبيعة الخدمة.','Open the product page to see troubleshooting tailored to that service.')+'</p></div><div class="common-problem-product-action"><select id="commonProblemProduct" aria-label="'+t('اختار الاشتراك','Choose a subscription')+'"><option value="">'+t('اختار الاشتراك…','Choose a subscription…')+'</option>'+selectOptions+'</select><button type="button" id="commonProblemProductGo">'+t('عرض حلول الاشتراك','View subscription fixes')+' ↗</button></div></section><section class="common-problem-contact"><div><span>'+t('لسه المشكلة موجودة؟','STILL NEED HELP?')+'</span><h2>'+t('خلّي الدعم يراجعها معاك.','Let support review it with you.')+'</h2><p>'+t('جهّز رقم الطلب وصورة رسالة الخطأ. لا ترسل كلمة المرور أو رموز التحقق.','Prepare your order reference and an error screenshot. Never send passwords or verification codes.')+'</p></div><a href="https://wa.me/201500950624" target="_blank" rel="noopener noreferrer">'+t('تواصل مع الدعم','Contact support')+' ↗</a></section>';
  host.querySelector('#commonProblemSearch').addEventListener('input',e=>{query=e.target.value;opened=null;update();});
  host.querySelectorAll('[data-problem-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.problemCategory;opened=null;update();}));
  host.querySelector('#commonProblemProductGo').addEventListener('click',()=>{const id=host.querySelector('#commonProblemProduct').value;if(id)global.location.href='/products/'+encodeURIComponent(id)+'.html#subscription-troubleshooting';});
  update();
 }
 render();doc.addEventListener('masterstore:localechange',render);
}
return {problems,categories,mount};
});